-- ============================================================
-- School Management System — Supabase (PostgreSQL) migration
-- Run once in Supabase SQL Editor. Safe to re-run (DROP IF EXISTS).
-- Generated from live MySQL schema (schema_v1..v8 applied).
-- ============================================================

DROP TABLE IF EXISTS routine_entries CASCADE;
DROP TABLE IF EXISTS promotion_history CASCADE;
DROP TABLE IF EXISTS results CASCADE;
DROP TABLE IF EXISTS exam_shares CASCADE;
DROP TABLE IF EXISTS ct_marks CASCADE;
DROP TABLE IF EXISTS device_tokens CASCADE;
DROP TABLE IF EXISTS guardian_links CASCADE;
DROP TABLE IF EXISTS homework CASCADE;
DROP TABLE IF EXISTS notifications CASCADE;
DROP TABLE IF EXISTS attendance CASCADE;
DROP TABLE IF EXISTS marks CASCADE;
DROP TABLE IF EXISTS exams CASCADE;
DROP TABLE IF EXISTS exam_events CASCADE;
DROP TABLE IF EXISTS holidays CASCADE;
DROP TABLE IF EXISTS app_settings CASCADE;
DROP TABLE IF EXISTS students CASCADE;
DROP TABLE IF EXISTS subjects CASCADE;
DROP TABLE IF EXISTS classes CASCADE;
DROP TABLE IF EXISTS sessions CASCADE;
DROP TABLE IF EXISTS activity_log CASCADE;
DROP TABLE IF EXISTS users CASCADE;
CREATE TABLE IF NOT EXISTS users (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  role          TEXT NOT NULL CHECK (role IN ('admin','teacher','guardian')),
  username      VARCHAR(50) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  name          VARCHAR(100) NOT NULL,
  email         VARCHAR(100),
  phone         VARCHAR(20),
  active        SMALLINT NOT NULL DEFAULT 1,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS sessions (
  id        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name      VARCHAR(20) NOT NULL UNIQUE,
  is_active SMALLINT NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS classes (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        VARCHAR(50) NOT NULL,
  section     VARCHAR(20) NOT NULL,
  group_name  VARCHAR(20),
  session_id  INTEGER REFERENCES sessions(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  teacher_id  INTEGER REFERENCES users(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  UNIQUE (name, section)
);
CREATE TABLE IF NOT EXISTS subjects (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          VARCHAR(60) NOT NULL,
  class_id      INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  teacher_id    INTEGER REFERENCES users(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  full_marks    INTEGER NOT NULL DEFAULT 100,
  pass_marks    INTEGER,
  group_name    VARCHAR(20) NOT NULL DEFAULT 'Compulsory',
  is_optional   SMALLINT NOT NULL DEFAULT 0,
  excluded_from_gpa SMALLINT NOT NULL DEFAULT 0,
  cq_full       INTEGER,
  mcq_full      INTEGER,
  practical_full INTEGER,
  subject_code  INTEGER,
  UNIQUE (class_id, name)
);
CREATE TABLE IF NOT EXISTS students (
  id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_code   VARCHAR(20) NOT NULL UNIQUE,
  name           VARCHAR(100) NOT NULL,
  dob            DATE,
  roll           INTEGER NOT NULL,
  class_id       INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  guardian_id    INTEGER REFERENCES users(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  guardian_name  VARCHAR(100),
  guardian_phone VARCHAR(20),
  guardian_email VARCHAR(100),
  address        VARCHAR(255),
  photo          VARCHAR(255),
  father_name    VARCHAR(100),
  mother_name    VARCHAR(100),
  birth_cert_no  VARCHAR(50),
  session_id     INTEGER,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (class_id, roll)
);
CREATE TABLE IF NOT EXISTS exam_events (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       VARCHAR(100) NOT NULL,
  session_id INTEGER REFERENCES sessions(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  start_date DATE,
  created_by INTEGER,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS exams (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       VARCHAR(150) NOT NULL,
  exam_type  TEXT NOT NULL DEFAULT 'class_test' CHECK (exam_type IN ('class_test','midterm','final')),
  class_id   INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  subject_id INTEGER NOT NULL REFERENCES subjects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  event_id   INTEGER REFERENCES exam_events(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  source     TEXT NOT NULL DEFAULT 'teacher' CHECK (source IN ('admin','teacher')),
  status     TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','published')),
  created_by INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  exam_date  DATE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS marks (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id   INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  exam_id      INTEGER NOT NULL REFERENCES exams(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  marks        NUMERIC(5,2) NOT NULL,
  total        NUMERIC(5,2) NOT NULL DEFAULT 100,
  comment      VARCHAR(255),
  cq           NUMERIC(5,2),
  mcq          NUMERIC(5,2),
  practical    NUMERIC(5,2),
  written      NUMERIC(5,2),
  absent       SMALLINT NOT NULL DEFAULT 0,
  recorded_by  INTEGER REFERENCES users(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  recorded_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  edit_until   TIMESTAMPTZ,
  UNIQUE (student_id, exam_id)
);
CREATE TABLE IF NOT EXISTS attendance (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id  INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  date        DATE NOT NULL,
  status      TEXT NOT NULL DEFAULT 'present' CHECK (status IN ('present','absent','late')),
  remark      VARCHAR(255),
  recorded_by INTEGER,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  is_escape          BOOLEAN   NOT NULL DEFAULT FALSE,
  escape_detected_at TIMESTAMPTZ,
  UNIQUE (student_id, date)
);

CREATE INDEX IF NOT EXISTS idx_attendance_escape
  ON attendance(date) WHERE is_escape = TRUE;
CREATE TABLE IF NOT EXISTS notifications (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id  INTEGER REFERENCES students(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  class_id    INTEGER REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  title       VARCHAR(150) NOT NULL,
  body        TEXT NOT NULL,
  type        TEXT NOT NULL DEFAULT 'general' CHECK (type IN ('attendance','result','general','notice','class_test_result','homework','complaint','special')),
  target_type TEXT NOT NULL DEFAULT 'all' CHECK (target_type IN ('all','class','section','students','guardians','teacher')),
  related_id  INTEGER,
  is_read     SMALLINT NOT NULL DEFAULT 0,
  created_by  INTEGER,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS homework (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  class_id    INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  subject_id  INTEGER REFERENCES subjects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  title       VARCHAR(150) NOT NULL,
  description TEXT,
  due_date    DATE,
  created_by  INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS ct_marks (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id   INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  subject_id   INTEGER NOT NULL REFERENCES subjects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  ct_no        SMALLINT NOT NULL DEFAULT 1,
  marks        NUMERIC(5,2) NOT NULL,
  full_marks   NUMERIC(5,2) NOT NULL DEFAULT 25,
  recorded_by  INTEGER,
  recorded_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  edit_until   TIMESTAMPTZ,
  UNIQUE (student_id, subject_id, ct_no)
);
CREATE TABLE IF NOT EXISTS exam_shares (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  exam_id    INTEGER NOT NULL REFERENCES exams(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  teacher_id INTEGER NOT NULL,
  created_by INTEGER,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (exam_id, teacher_id)
);
CREATE TABLE IF NOT EXISTS guardian_links (
  id                  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guardian_id         INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  student_id          INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  role                TEXT NOT NULL DEFAULT 'sibling' CHECK (role IN ('primary','sibling')),
  status              TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
  requester_student_id INTEGER REFERENCES students(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  decided_by          INTEGER REFERENCES users(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  remark              VARCHAR(255),
  requested_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_at          TIMESTAMPTZ,
  UNIQUE (guardian_id, student_id)
);
CREATE TABLE IF NOT EXISTS device_tokens (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    INTEGER NOT NULL,
  role       VARCHAR(20) NOT NULL,
  fcm_token  TEXT NOT NULL UNIQUE,
  platform   VARCHAR(20) DEFAULT 'android',
  active     SMALLINT NOT NULL DEFAULT 1,
  last_seen  TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (fcm_token)
);
CREATE TABLE IF NOT EXISTS holidays (
  date  DATE NOT NULL PRIMARY KEY,
  title VARCHAR(150) NOT NULL
);
CREATE TABLE IF NOT EXISTS app_settings (
  setting_key   VARCHAR(60) NOT NULL PRIMARY KEY,
  setting_value TEXT
);
CREATE TABLE IF NOT EXISTS promotion_history (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id    INTEGER NOT NULL,
  from_class_id INTEGER NOT NULL,
  to_class_id   INTEGER,
  final_gpa     NUMERIC(4,2) DEFAULT 0,
  decision      TEXT DEFAULT 'promoted' CHECK (decision IN ('promoted','retained','readmission')),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS results (
  id                   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  student_id           INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  exam_id              INTEGER NOT NULL,
  total_gpa_without_4th NUMERIC(4,2) DEFAULT 0,
  gpa_4th_bonus        NUMERIC(4,2) DEFAULT 0,
  final_gpa            NUMERIC(4,2) DEFAULT 0,
  result_status        TEXT DEFAULT 'ABSENT' CHECK (result_status IN ('PASSED','FAILED','ABSENT')),
  teacher_remarks      TEXT,
  computed_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (student_id, exam_id)
);
CREATE TABLE IF NOT EXISTS routine_entries (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  class_id   INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  day        SMALLINT NOT NULL,
  period     SMALLINT NOT NULL,
  subject_id INTEGER,
  teacher_id INTEGER,
  UNIQUE (class_id, day, period)
);

-- ===========================================================================
-- Routine Management v2 (Multi-Section/Group, Subject Aliasing, Matrix view)
-- Replaces routine_entries at runtime via migration; kept in file for reference.
-- ===========================================================================
CREATE TABLE IF NOT EXISTS time_slots (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slot_order  SMALLINT NOT NULL UNIQUE,
  label       VARCHAR(50) NOT NULL,
  start_time  TIME,
  end_time    TIME,
  is_break    BOOLEAN DEFAULT FALSE
);

