CREATE TABLE IF NOT EXISTS routines (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  teacher_id   INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  subject_id   INTEGER NOT NULL REFERENCES subjects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  day          SMALLINT NOT NULL CHECK (day >= 0 AND day <= 4),
  time_slot_id INTEGER NOT NULL REFERENCES time_slots(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  notes        TEXT,
  room         VARCHAR(30),
  created_at   TIMESTAMPTZ DEFAULT now(),
  UNIQUE (teacher_id, day, time_slot_id)
);
CREATE TABLE IF NOT EXISTS routine_notification_log (
  id         BIGSERIAL PRIMARY KEY,
  routine_id INTEGER NOT NULL REFERENCES routines(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  event_date DATE NOT NULL,
  event      VARCHAR(20) NOT NULL CHECK (event IN ('reminder','start')),
  sent_at    TIMESTAMPTZ DEFAULT now(),
  UNIQUE (routine_id, event_date, event)
);
CREATE TABLE IF NOT EXISTS routine_sections (
  routine_id INTEGER NOT NULL REFERENCES routines(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  class_id   INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  section    VARCHAR(20) NOT NULL,
  PRIMARY KEY (routine_id, class_id, section)
);
CREATE TABLE IF NOT EXISTS routine_groups (
  routine_id INTEGER NOT NULL REFERENCES routines(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  class_id   INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  group_name VARCHAR(20) NOT NULL,
  PRIMARY KEY (routine_id, class_id, group_name)
);
CREATE TABLE IF NOT EXISTS subject_aliases (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  subject_id    INTEGER NOT NULL REFERENCES subjects(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  alias_name    VARCHAR(120) NOT NULL,
  student_field VARCHAR(50) NOT NULL DEFAULT 'religion',
  field_value   VARCHAR(50) NOT NULL,
  class_id      INTEGER REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  UNIQUE (subject_id, student_field, field_value, class_id)
);

-- Routine delete approval flow (added 2026-09-15): teacher requests deletion,
-- admin approves via /routine/admin/delete-requests/:id/approve (or rejects).
-- No FK so history is preserved after the routine row is deleted.
CREATE TABLE IF NOT EXISTS routine_delete_requests (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  routine_id    INTEGER NOT NULL,
  teacher_id    INTEGER NOT NULL,
  subject_name  VARCHAR(150),
  class_details TEXT,
  day           SMALLINT,
  time_slot_id  INTEGER,
  reason        TEXT,
  status        TEXT NOT NULL DEFAULT 'pending',
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_at    TIMESTAMPTZ
);

ALTER TABLE students ADD COLUMN IF NOT EXISTS religion VARCHAR(30);

