CREATE TABLE IF NOT EXISTS activity_log (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    INTEGER REFERENCES users(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  action     VARCHAR(100) NOT NULL,
  detail     TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_subjects_teacher ON subjects(teacher_id);
CREATE INDEX IF NOT EXISTS idx_students_guardian ON students(guardian_id);
CREATE INDEX IF NOT EXISTS idx_exams_class ON exams(class_id);
CREATE INDEX IF NOT EXISTS idx_exams_subject ON exams(subject_id);
CREATE INDEX IF NOT EXISTS idx_exams_event ON exams(event_id);
CREATE INDEX IF NOT EXISTS idx_marks_exam ON marks(exam_id);
CREATE INDEX IF NOT EXISTS idx_marks_recorded_by ON marks(recorded_by);
CREATE INDEX IF NOT EXISTS idx_attendance_recorded_by ON attendance(recorded_by);
CREATE INDEX IF NOT EXISTS idx_nots_student ON notifications(student_id);
CREATE INDEX IF NOT EXISTS idx_nots_class ON notifications(class_id);
CREATE INDEX IF NOT EXISTS idx_gl_student ON guardian_links(student_id);
CREATE INDEX IF NOT EXISTS idx_gl_status ON guardian_links(status);
CREATE INDEX IF NOT EXISTS idx_tokens_user ON device_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_classes_session ON classes(session_id);
CREATE INDEX IF NOT EXISTS idx_classes_teacher ON classes(teacher_id);
CREATE INDEX IF NOT EXISTS idx_events_session ON exam_events(session_id);
CREATE INDEX IF NOT EXISTS idx_hw_class ON homework(class_id);
CREATE INDEX IF NOT EXISTS idx_hw_subject ON homework(subject_id);
CREATE INDEX IF NOT EXISTS idx_hw_creator ON homework(created_by);
CREATE INDEX IF NOT EXISTS idx_ct_subject ON ct_marks(subject_id);
CREATE INDEX IF NOT EXISTS idx_share_teacher ON exam_shares(teacher_id);
CREATE INDEX IF NOT EXISTS idx_rt_class ON routine_entries(class_id);

