-- ===========================================================================
-- NCTB SUBJECT RESEED (applied 2026-09-15 via backend/seed_nctb_subjects.js)
-- Cleans ALL previous subject records and seeds the official NCTB class-wise
-- subject structure for Class 6..10 / SSC. Idempotent (wipes + re-inserts).
--   Class 6-8 (General)      : 13 subjects per class row
--   Class 9/10 + SSC Batch   : Science 16, Commerce 15, Arts 16 per class row
--     core (all tracks)      : Bangla 1st, Bangla 2nd, English 1st, English 2nd,
--                              Mathematics, ICT, Religion & Moral Education,
--                              Physical Education & Health, Career Education
--     Science extra          : Bangladesh & Global Studies, Physics, Chemistry,
--                              Biology
--     Commerce extra         : General Science, Accounting, Finance & Banking,
--                              Business Entrepreneurship
--     Arts extra             : General Science, History of Bangladesh & World
--                              Civilization, Geography & Environment,
--                              Economics* / Civics & Citizenship*  (* = elective)
--     4th optional pool      : Agriculture Studies, Home Science
--     (Science-only 4th pool): Higher Mathematics
-- The seeder also preserves teacher->subject assignments, per-student subject
-- allocations (student_subjects) and Religion subject_aliases via name matching.
-- ===========================================================================
-- CLASS-TEACHER REQUEST WORKFLOW (added 2026-09-15):
-- teachers request to become class teacher; admin approves/rejects.
CREATE TABLE IF NOT EXISTS class_teacher_requests (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  class_id    INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  teacher_id  INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  status      TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
  note        VARCHAR(255),
  decided_by  INTEGER REFERENCES users(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_at  TIMESTAMPTZ,
  UNIQUE (class_id, teacher_id)
);
